import java.util.*;
public class ImmutableClass {
  private int a,b;
  private Stack<String> st;
  public ImmutableClass(int a,int  b,
  Stack<String> st) {
    this.a=a;
    this.b=b;
    this.st=st;
  }
  public int getA() {return a;}
  public int getB() {return b;}
  public Stack<String> getST(){
    Stack<String> t=new Stack<String>();
    t.addAll(st);
    return t;
  }
}

